namespace NotificationsApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        for (var i = 0; i < 5; i++)
        {
            _notifications.Add(new Notification(
                _nextId++,
                $"Welcome notification #{i + 1}",
                DateTime.UtcNow.AddMinutes(-10 + i)));
        }
    }

    /// <summary>Returns all notifications.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given ID.</summary>
    public List<Notification> GetSince(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > lastSeenId).ToList();
        }
    }

    /// <summary>
    /// Simulates an external system pushing a new notification.
    /// Called by a hosted background service to keep fake data flowing.
    /// </summary>
    public void Add(string message)
    {
        lock (_lock)
        {
            _notifications.Add(new Notification(_nextId++, message, DateTime.UtcNow));
        }
    }
}

namespace NotificationsApp.Services;

/// <summary>
/// Background hosted service that adds a fake notification every 8 seconds
/// so the polling loop on the page has something new to pick up.
/// </summary>
public class NotificationGeneratorService : BackgroundService
{
    private readonly NotificationService _notifications;
    private int _counter;

    public NotificationGeneratorService(NotificationService notifications)
    {
        _notifications = notifications;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            _counter++;
            _notifications.Add($"New event – item {_counter} arrived");
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService Svc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
</h1>

@if (_notifications.Count == 0)
{
    <p><em>No notifications yet.</em></p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>@n.Message</div>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification> _notifications = new();
    private CancellationTokenSource? _cts;

    // Runs during both prerender AND interactive init.
    // PersistentComponentState would also work, but for a simple list
    // we just reload from the singleton on first render — the data is
    // already in memory so there is no duplicate HTTP/DB call.
    protected override void OnInitialized()
    {
        _notifications = Svc.GetAll();
    }

    // Called only once the circuit is live (never during static SSR).
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (!firstRender) return;

        _cts = new CancellationTokenSource();
        _ = PollForNotificationsAsync(_cts.Token);

        await Task.CompletedTask;
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (OperationCanceledException)
            {
                return;
            }

            var lastId = _notifications.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = Svc.GetSince(lastId);
            if (newer.Count > 0)
            {
                _notifications.AddRange(newer);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

